from pathlib import Path
p=Path('/mnt/data/aifilmwork/index.html')
s=p.read_text()
s=s.replace('''            <label>Overall Direction<textarea id="projectDirection" rows="4" placeholder="Describe the animation style, mood, visual look, camera style, atmosphere and creative rules..."></textarea></label>''','''            <label>Overall Direction<textarea id="projectDirection" rows="4" placeholder="Describe the animation style, mood, visual look, camera style, atmosphere and creative rules..."></textarea></label>
            <div class="character-setup-block">
              <h3>Characters for this project <span class="soft-tag">Optional</span></h3>
              <p class="helper">Select saved characters before creating scenes. Leave empty if you want AI to invent characters.</p>
              <label>Saved characters<select id="projectCharacters" multiple size="4"></select></label>
              <label>Story name mapping<textarea id="projectAliases" rows="3" placeholder="Jessica -> MAYA&#10;Tom -> RAVI"></textarea><small class="helper">One mapping per line. The name on the left is used in your story; the saved character on the right will appear in the generated scenes.</small></label>
            </div>''')
s=s.replace('''<li>AI can invent suitable characters when your library is empty.</li><li>AI generates a cinematic still image for each scene.</li>''','''<li>Choose saved characters and optional story-name mappings before creating the project.</li><li>AI invents characters only when no saved character is assigned or detected.</li><li>AI generates a cinematic still image for each scene; you can replace it by generating again or uploading your own image.</li>''')
s=s.replace('''<div class="ai-action-row"><button type="button" class="secondary-button" data-generate-scene-image="${i}">✦ Generate scene image</button><button type="button" class="secondary-button" data-speak-dialogue="${i}">▶ Preview dialogue voice</button></div>${s.generated_image?`<img class="ai-scene-image" src="${s.generated_image}" alt="Generated scene ${i+1}">`:""}''','''<div class="dialogue-lines" data-dialogue-lines>${dialogueLineMarkup(s,i)}</div><div class="ai-action-row"><button type="button" class="secondary-button" data-add-dialogue="${i}">＋ Add character dialogue</button><button type="button" class="secondary-button" data-generate-scene-image="${i}">✦ Generate / replace image</button><label class="secondary-button upload-scene-label">↑ Upload image<input type="file" accept="image/*" data-upload-scene-image="${i}" hidden></label>${s.generated_image?`<button type="button" class="text-button danger-text" data-remove-scene-image="${i}">Remove image</button>`:""}</div>${s.generated_image?`<img class="ai-scene-image" src="${s.generated_image}" alt="Scene ${i+1} image"><small class="helper">Image preview. Generated artwork uses text prompts; exact pixel-level matching to character reference images is not guaranteed by the connected model.</small>`:""}''')
p.write_text(s)
